example.code:
// WRONG — capability decides WHEN (policy)
function ensureSession(): Session {
  if (session?.isValid) return session;
  return createSession();
}

// CORRECT — capability provides mechanism, orchestrator owns policy
// capability:
function createSession(): Session { return api.createSession(); }
// orchestrator:
function getSession(): Session {
  return session?.isValid ? session : createSession();
}

// WRONG — monolithic 500+ line entry point
export function activate(context) {
  // Task logic... Quick logic... Docs logic... Config logic...
}

// CORRECT — thin composition root with domain orchestrators
export function activate(context) {
  const tasks = createTasksOrchestrator(deps);
  const quicks = createQuicksOrchestrator(deps);
}

// WRONG — boolean flags allow impossible states, completedAt exists when not done
interface Task {
  isLoading: boolean; hasError: boolean; isComplete: boolean;
  completedAt?: Date;  // nothing stops this being set when isComplete is false
}

// CORRECT — illegal states are unrepresentable
type Task =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'error'; readonly error: Error }
  | { status: 'complete'; readonly data: TaskData; readonly completedAt: Date };

// completedAt ONLY exists when status is 'complete' — structurally enforced
function getIcon(task: Task): string {
  switch (task.status) {
    case 'idle': return 'circle';
    case 'loading': return 'sync';
    case 'error': return 'alert';
    case 'complete': return 'check';
    default: { const _: never = task; return _; }
  }
}

// WRONG — capability throws on expected failure
function readConfig(path: string): Config {
  return JSON.parse(fs.readFileSync(path, 'utf-8'));  // throws!
}

// CORRECT — returns typed Result
function readConfig(path: string): Result<Config, 'not-found' | 'parse-error'> {
  if (!fs.existsSync(path)) return err('not-found');
  try { return ok(JSON.parse(fs.readFileSync(path, 'utf-8'))); }
  catch { return err('parse-error'); }
}

// WRONG — imperative loop with mutation
const result: string[] = [];
for (let i = 0; i < tasks.length; i++) {
  if (tasks[i].status === 'active') result.push(tasks[i].id);
}

// CORRECT — declarative pipeline
const result = tasks
  .filter((t) => t.status === 'active')
  .map((t) => t.id);

// WRONG — push-based construction
const args: string[] = [];
args.push('--format', opts.format);
if (opts.verbose) args.push('--verbose');

// CORRECT — expression-based construction
const args = [
  '--format', opts.format,
  ...(opts.verbose ? ['--verbose'] : []),
];

// WRONG — imports and constructs dependency internally
import { createXmlParser } from './xml-parser.computer';
export function createTaskHandler() {
  const parser = createXmlParser();  // hidden dependency!
  return { handle: (xml: string) => parser.parse(xml) };
}

// CORRECT — receives dependency via factory parameter
export function createTaskHandler(deps: { parser: XmlParser }) {
  return { handle: (xml: string) => deps.parser.parse(xml) };
}

// WRONG — class with this, hidden state, implicit DI
class TaskService {
  private tasks: Task[] = [];
  constructor(private readonly fs: FileSystem) {}
  addTask(t: Task) { this.tasks.push(t); }
}

// CORRECT — factory with closure, explicit interface, no this
interface TaskCapability { readonly addTask: (t: Task) => readonly Task[]; }
function createTaskCapability(deps: { fs: FileSystem }): TaskCapability {
  let tasks: readonly Task[] = [];
  return { addTask: (t) => { tasks = [...tasks, t]; return tasks; } };
}

// WRONG — if/else chain for value mapping
function getIcon(status: string): string {
  if (status === 'active') return 'play';
  else if (status === 'done') return 'check';
  else if (status === 'error') return 'alert';
  else return 'circle';
}

// CORRECT — Record lookup, declarative and exhaustive
const statusIcons = {
  active: 'play',
  done: 'check',
  error: 'alert',
  idle: 'circle',
} as const satisfies Record<Status, string>;

function getIcon(status: Status): string {
  return statusIcons[status];
}

// WRONG — mutates caller's object
function addDefaults(opts: Options): Options {
  opts.timeout ??= 5000;
  return opts;
}

// CORRECT — returns new object
function addDefaults(opts: Options): Options {
  return { timeout: 5000, ...opts };
}
